function mapPreview(response,input,now=Date.now()){
 const fail=(code,retryable=false)=>({schema:'fluxproof-n8n-preview.v1',state:'source_check_failed',code,retryable,monitorCreated:false,paymentAttempted:false,changeState:'not_observed',handoff:null});
 if(!response||response.error||!Number.isInteger(response.statusCode))return fail('transport_error',true);
 let b;try{b=typeof response.body==='string'?JSON.parse(response.body):response.body}catch{return fail('response_not_json')}
 if(!b||typeof b!=='object'||Array.isArray(b))return fail('response_contract_invalid');
 if(response.statusCode!==200)return {...fail(typeof b.error==='string'?b.error:'http_error',response.statusCode===429||response.statusCode>=500),httpStatus:response.statusCode};
 if(b.schema!=='fluxproof-preflight.v1'||b.fetchable!==true||b.content_included!==false||typeof b.final_url!=='string'||!/^https?:\/\/[^\s/@?#]+(?:[/?#][^\s]*)?$/.test(b.final_url)||!/^[a-f0-9]{64}$/.test(b.content_sha256||'')||!Number.isInteger(b.http_status)||b.http_status<200||b.http_status>299||!Number.isSafeInteger(b.bytes)||b.bytes<=0)return fail('response_contract_invalid');
 const observed=typeof b.observed_at==='string'?Date.parse(b.observed_at):NaN;
 if(!Number.isFinite(observed)||observed>now+60000||observed<now-900000)return fail('receipt_time_invalid');
 if('content' in b||'content_text' in b)return fail('unexpected_content');
 return {schema:'fluxproof-n8n-preview.v1',state:'source_readable_not_monitored',monitorCreated:false,paymentAttempted:false,changeState:'not_observed',submittedUrl:input.url,finalUrl:b.final_url,observedAt:b.observed_at,contentSha256:b.content_sha256,bytes:b.bytes,handoff:{url:'https://fluxproof.neoaethel.workers.dev/quickstart',automaticPurchase:false,instruction:'Choose a free key or explicitly authorized paid access separately. Create a baseline before interpreting changes. One preview is not monitor history; failed fetches never mean unchanged. Never paste keys into this recipe.'}};
}
const rows=$input.all();if(rows.length!==1)throw new Error('Exactly one response required');return [{json:mapPreview(rows[0].json,$('Choose input').first().json),pairedItem:{item:0}}];
